def parse_sides(s):
    main = []
    imp = []
    order = []
    parts = s.split('||')
    if len(parts) > 1:
        order = parts[1].split()
    sub = parts[0].split('|')
    main = sub[0].split()
    if len(sub) > 1:
        imp = sub[1].split()
    return main, imp, order

def expand_vars(text, envs):
    for _ in range(10):
        if '$' not in text:
            break
        prev = text
        text = text.replace('$$', '\x00')
        text = text.replace('$ ', ' ')
        def repl(m):
            var = m.group(1) or m.group(2)
            if var == 'in': return envs[0].get('in', '')
            if var == 'out': return envs[0].get('out', '')
            for env in envs:
                if var in env: return env[var]
            return ""
        text = re.sub(r'\$\{([a-zA-Z0-9_.-]+)\}', repl, text)
        text = re.sub(r'\$([a-zA-Z0-9_-]+)', repl, text)
        text = text.replace('\x00', '$')
        if text == prev:
            break
    return text

def parse_ninja(filename):
    global_vars = {}
    rules = {}
    builds = []
    defaults = []

    with open(filename, 'r') as f:
        lines = f.readlines()

    i = 0
    while i < len(lines):
        line = lines[i].rstrip('\n')
        while line.endswith('$') and i + 1 < len(lines):
            i += 1
            line = line[:-1] + lines[i].lstrip().rstrip('\n')

        if '#' in line:
            line = line[:line.find('#')]

        line = line.strip()
        if not line:
            i += 1
            continue

        if line.startswith('rule '):
            rule_name = line.split()[1]
            rule_vars = {}
            i += 1
            while i < len(lines) and (lines[i].startswith(' ') or lines[i].startswith('\t')):
                rl = lines[i].strip()
                if rl and not rl.startswith('#') and '=' in rl:
                    k, v = rl.split('=', 1)
                    rule_vars[k.strip()] = v.strip()
                i += 1
            rules[rule_name] = rule_vars
            continue

        elif line.startswith('build '):
            build_line = line[6:]
            if ':' not in build_line:
                i += 1
                continue
            left, right = build_line.split(':', 1)
            outs, imp_outs, _ = parse_sides(left)
            right_parts = right.strip().split(None, 1)
            rule = right_parts[0]
            rest = right_parts[1] if len(right_parts) > 1 else ""
            ins, imp_ins, order_ins = parse_sides(rest)

            build_vars = {}
            i += 1
            while i < len(lines) and (lines[i].startswith(' ') or lines[i].startswith('\t')):
                rl = lines[i].strip()
                if rl and not rl.startswith('#') and '=' in rl:
                    k, v = rl.split('=', 1)
                    build_vars[k.strip()] = v.strip()
                i += 1

            builds.append({
                'outs': outs, 'imp_outs': imp_outs,
                'rule': rule, 'ins': ins, 'imp_ins': imp_ins, 'order_ins': order_ins,
                'vars': build_vars
            })
            continue

        elif line.startswith('default '):
            defaults.extend(line[8:].split())

        elif '=' in line:
            k, v = line.split('=', 1)
            global_vars[k.strip()] = expand_vars(v.strip(), [global_vars])

        i += 1

    return global_vars, rules, builds, defaults

def main():
    mock_cli()

    args = sys.argv[1:]
    build_file = "build.ninja"
    targets = []

    i = 0
    verbose = False
    dry_run = False
    cwd = None

    while i < len(args):
        if args[i] == '-f':
            build_file = args[i+1]
            i += 2
            continue
        elif args[i] == '-C':
            cwd = args[i+1]
            i += 2
            continue
        elif args[i] == '-v' or args[i] == '--verbose':
            verbose = True
            i += 1
            continue
        elif args[i] == '-n':
            dry_run = True
            i += 1
            continue
        elif args[i].startswith('-'):
            if args[i] in ('-j', '-k', '-l', '-d', '-t', '-w'):
                i += 2
            else:
                i += 1
            continue
        else:
            targets.append(args[i])
            i += 1

    if cwd:
        print(f"ninja: Entering directory `{cwd}`")
        os.chdir(cwd)

    if not os.path.exists(build_file):
        print(f"ninja: error: loading '{build_file}': No such file or directory")
        sys.exit(1)

    g_vars, rules, builds, defaults = parse_ninja(build_file)

    target_to_build = {}
    for b in builds:
        for o in b['outs']:
            target_to_build[o] = b

    if not targets:
        if defaults:
            targets = defaults
        else:
            all_ins = set()
            for b in builds:
                all_ins.update(b['ins'])
                all_ins.update(b['imp_ins'])
                all_ins.update(b['order_ins'])
            targets = [b['outs'][0] for b in builds if not set(b['outs']).intersection(all_ins)]
            if not targets and builds:
                targets = [builds[0]['outs'][0]]

    log = {}
    if os.path.exists('.ninja_log'):
        with open('.ninja_log', 'r') as f:
            for line in f:
                if line.startswith('#'): continue
                parts = line.strip().split('\t')
                if len(parts) >= 5:
                    log[parts[3]] = parts[4]

    visited = set()
    temp_mark = set()
    topo_order = []

    def visit(node):
        if node in temp_mark:
            print(f"ninja: error: dependency cycle: {node} ...")
            sys.exit(1)
        if node in visited:
            return

        if node in target_to_build:
            temp_mark.add(node)
            b = target_to_build[node]
            for n in b['ins'] + b['imp_ins'] + b['order_ins']:
                visit(n)
            temp_mark.remove(node)
            visited.add(node)
            if b not in topo_order:
                topo_order.append(b)
        else:
            if not os.path.exists(node):
                print(f"ninja: error: '{node}', needed by '...', missing and no known rule to make it")
                sys.exit(1)
            visited.add(node)

    for t in targets:
        visit(t)

    dirty_builds = []
    dirty_files = set()

    for b in topo_order:
        envs = [b['vars'], rules.get(b['rule'], {}), g_vars]
        if 'in' not in envs[0]:
            envs[0]['in'] = ' '.join(b['ins'])
        if 'out' not in envs[0]:
            envs[0]['out'] = ' '.join(b['outs'])

        cmd_raw = rules.get(b['rule'], {}).get('command', '')
        cmd = expand_vars(cmd_raw, envs)

        h = hashlib.md5(cmd.encode()).hexdigest()[:16]
        b['cmd'] = cmd
        b['cmd_hash'] = h

        desc_raw = rules.get(b['rule'], {}).get('description', '')
        b['desc'] = expand_vars(desc_raw, envs)

        dirty = False
        for out in b['outs']:
            if not os.path.exists(out):
                dirty = True
                break

        if not dirty:
            for in_file in b['ins'] + b['imp_ins']:
                if in_file in dirty_files:
                    dirty = True
                else:
                    out_mtime = min((os.path.getmtime(o) for o in b['outs']), default=0)
                    if os.path.getmtime(in_file) > out_mtime:
                        dirty = True

        if not dirty:
            for out in b['outs']:
                if log.get(out) != h:
                    dirty = True
                    break

        if dirty:
            dirty_builds.append(b)
            for out in b['outs']:
                dirty_files.add(out)

    if not dirty_builds:
        print("ninja: no work to do.")
        sys.exit(0)

    total = len(dirty_builds)
    current = 0
    start_time_global = time.time()

    for b in dirty_builds:
        current += 1
        desc = b['desc'] if b['desc'] and not verbose else b['cmd']
        print(f"[{current}/{total}] {desc}")

        if not dry_run:
            t0 = time.time()
            ret = subprocess.call(b['cmd'], shell=True)
            if ret != 0:
                print(f"FAILED: {' '.join(b['outs'])}")
                print(b['cmd'])
                sys.exit(1)
            t1 = time.time()

            if not os.path.exists('.ninja_log'):
                with open('.ninja_log', 'w') as f:
                    f.write("# ninja log v7\n")

            with open('.ninja_log', 'a') as f:
                start_ms = int((t0 - start_time_global) * 1000)
                end_ms = int((t1 - start_time_global) * 1000)
                for out in b['outs']:
                    mtime = int(time.time() * 1000000000)
                    f.write(f"{start_ms}\t{end_ms}\t{mtime}\t{out}\t{b['cmd_hash']}\n")

if __name__ == "__main__":
    main()
